css:
.content.p37-page { --p37-pad-x: var(--s-3); --p37-pad-y: var(--s-3); padding: var(--p37-pad-y) var(--p37-pad-x); min-height: 100%; display: flex; flex-direction: column; gap: var(--s-4); }
@media (min-width: 48rem) and (min-height: 31.25rem) { .content.p37-page { --p37-pad-x: var(--s-5); --p37-pad-y: var(--s-4); } }
.p37-foot { position: sticky; bottom: 0; z-index: 1; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--s-2); margin: auto calc(var(--p37-pad-x) * -1) calc(var(--p37-pad-y) * -1); padding: var(--s-3) var(--p37-pad-x); background: var(--white); border-top: var(--w1) solid var(--rule); }
.p37-col { display: grid; gap: var(--s-4); width: 100%; max-width: 30rem; align-content: start; }
.p37-head { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2) var(--s-3); }
.p37-titlerow { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--s-2) var(--s-3); width: 100%; }
.p37-state { display: flex; align-items: center; gap: var(--s-3); padding-block: var(--s-3); }
.p37-err { --frame-w: var(--w2); }
.p37-wrapbtn { flex-wrap: wrap; }
.p37-wrapbtn .banner__text { flex: 1 1 14rem; }
.input.p37-focus { border: var(--w2) solid var(--blue); padding-inline: calc(var(--s-3) - var(--w1)); }
.p37-note { display: grid; gap: var(--s-2); justify-items: start; }
.p37-export .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p37-signin { display: grid; gap: var(--s-2); }   
.p37-signin .btn { width: 100%; }
.p37-google { gap: var(--s-3); }
.p37-g { font-weight: var(--fw-bold); font-size: var(--fs-body); }

.p37-ro { display: grid; gap: var(--s-3); margin: 0; }
.p37-ro > div { display: grid; gap: var(--s-1); }
.p37-ro dd { margin: 0; font-size: var(--fs-body); line-height: var(--lh-body); overflow-wrap: anywhere; }
.select.p37-select[aria-invalid="true"] { border: var(--w2) solid var(--terra); padding-inline: calc(var(--s-3) - var(--w1)); }
.select.p37-select[aria-disabled="true"] { border-color: var(--c-disabled-border); color: var(--c-disabled-text); cursor: not-allowed; }
.p37-tzmenu { width: 100%; margin-top: var(--s-2); }
.p37-tzlist { display: grid; gap: var(--s-1); max-height: 14rem; overflow: auto; }
.p37-nf { padding: var(--s-2) var(--s-3); }
.p37-zone { display: grid; gap: var(--s-2); justify-items: start; padding: var(--s-3); }
.p37-suggest { display: grid; gap: var(--s-2); width: 100%; }
.p37-suggest .row { flex-wrap: wrap; }
.p37-dim { color: var(--c-disabled-text); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
